{
    "organisationId": "{{orgId}}",
    "name": "Balance Sheet Manual",
    "description": "This is a balance sheet",
    "reportTemplateType": "BALANCE_SHEET",
    "dataMode": "USER",
    "fields": [
        {
            "fieldName": "Assets",
            "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
            "negated": false,
            "childFields": [
                {
                    "fieldName": "Non Current Assets",
                    "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                    "negated": false,
                    "childFields": [
                        {
                            "fieldName": "Tangible Assets",
                            "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                            "negated": false
                        },
                        {
                            "fieldName": "Intangible Assets",
                            "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                            "negated": false
                        },
                        {
                            "fieldName": "Investments",
                            "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                            "negated": false
                        },
                        {
                            "fieldName": "Financial Assets",
                            "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                            "negated": false
                        }
                    ]
                },
                {
                    "fieldName": "Current Assets",
                    "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                    "negated": false,
                    "childFields": [
                        {
                            "fieldName": "Prepayments and other short term assets",
                            "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                            "negated": false
                        },
                        {
                            "fieldName": "Other Receivables",
                            "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                            "negated": false
                        },
                        {
                            "fieldName": "Crypto Assets",
                            "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                            "negated": false
                        },
                        {
                            "fieldName": "Cash and Cash equivalents",
                            "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                            "negated": false
                        }
                    ]
                }
            ]
        },
        {
            "fieldName": "Liabilities",
            "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
            "negated": false,
            "childFields": [
                {
                    "fieldName": "Non Current Liabilities",
                    "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                    "negated": false,
                    "childFields": [
                        {
                            "fieldName": "Provisions",
                            "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                            "negated": true
                        }
                    ]
                },
                {
                    "fieldName": "Current Liabilities",
                    "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                    "negated": false,
                    "childFields": [
                        {
                            "fieldName": "Trade accounts payables",
                            "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                            "negated": true
                        },
                        {
                            "fieldName": "Other short term Liabilities",
                            "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                            "negated": true
                        },
                        {
                            "fieldName": "Accruals and short term provisions",
                            "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                            "negated": true
                        }
                    ]
                }
            ]
        },
        {
            "fieldName": "Capital",
            "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
            "negated": false,
            "childFields": [
                {
                    "fieldName": "Capital",
                    "dateRange": "ACCUMULATED_START_TO_PERIOD_END",
                    "negated": true
                },
                {
                    "fieldName": "Profit fort the year",
                    "dateRange": "ACCUMULATED_YEAR_TO_PERIOD_END",
                    "negated": true
                },
                {
                    "fieldName": "Results carried forward",
                    "dateRange": "ACCUMULATED_PREVIOUS_YEAR_TO_PREVIOUS_YEAR_END",
                    "negated": true
                }
            ]
        }
    ],
    "validationRules": [
        {
            "name": "Balanced",
            "operator": "EQUAL",
            "leftSideTerms": [
                {
                    "fieldName": "Assets",
                    "operation": "ADD"
                }
            ],
            "rightSideTerms": [
                {
                    "fieldName": "Liabilities",
                    "operation": "ADD"
                },
                {
                    "fieldName": "Capital",
                    "operation": "ADD"
                }
            ]
        }
    ]
}
